-- One-time editorial titles for all 688 starter quote entries. No schema change.
-- Only exact original ID/library/title/body matches are changed, including archived entries.
-- Custom titles or bodies and saved-meeting snapshots are never rewritten.
START TRANSACTION;
UPDATE organizations SET sequence=sequence;
CREATE TEMPORARY TABLE mmb_quote_titles (
 record_id CHAR(36) PRIMARY KEY,
 old_title VARCHAR(300) NOT NULL,
 body_hash CHAR(64) NOT NULL,
 new_title VARCHAR(300) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TEMPORARY TABLE mmb_quote_update (
 ordinal BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
 organization_id CHAR(36) NOT NULL,
 record_id CHAR(36) NOT NULL,
 new_version INT NOT NULL,
 base_sequence BIGINT UNSIGNED NOT NULL,
 new_payload JSON NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
SELECT r.organization_id,r.id,r.version+1,o.sequence,
 JSON_SET(r.payload,'$.title',q.new_title,'$.version',r.version+1,'$.updatedAt',DATE_FORMAT(UTC_TIMESTAMP(),'%Y-%m-%dT%H:%i:%s.000Z'))
FROM records r JOIN organizations o ON o.id=r.organization_id JOIN mmb_quote_titles q ON q.record_id=r.id
WHERE r.kind='items'
 AND JSON_UNQUOTE(JSON_EXTRACT(r.payload,'$.libraryId'))='00000000-0000-4000-8000-000000000008'
 AND BINARY JSON_UNQUOTE(JSON_EXTRACT(r.payload,'$.title'))=BINARY q.old_title
 AND SHA2(JSON_UNQUOTE(JSON_EXTRACT(r.payload,'$.description')),256)=q.body_hash;
SELECT organization_id,'items',record_id,new_version,new_payload,UTC_TIMESTAMP() FROM mmb_quote_update;
UPDATE records r JOIN mmb_quote_update c ON c.organization_id=r.organization_id AND c.record_id=r.id AND r.kind='items'
SET r.version=c.new_version,r.payload=c.new_payload,r.updated_at=UTC_TIMESTAMP();
SELECT organization_id,base_sequence+ordinal,'items',record_id FROM mmb_quote_update;
UPDATE organizations o JOIN (SELECT organization_id,MAX(base_sequence+ordinal) seq FROM mmb_quote_update GROUP BY organization_id) c ON c.organization_id=o.id SET o.sequence=c.seq;
DROP TEMPORARY TABLE mmb_quote_update;
DROP TEMPORARY TABLE mmb_quote_titles;
COMMIT;
